package com.pcguard.repository; import com.pcguard.entity.Fault; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.transaction.annotation.Transactional; import java.util.*; public interface FaultRepository extends JpaRepository<Fault,Long>{ List<Fault> findByComputerIdOrderByDetectedAtDesc(Long id); List<Fault> findByStatusOrderByDetectedAtDesc(Fault.Status status); Optional<Fault> findByComputerIdAndTypeAndStatus(Long id,String type,Fault.Status status); long countByStatus(Fault.Status status); @Transactional void deleteByComputerId(Long computerId); }
